window.LS_FONT = {"400": "", "700": ""};

// html2canvas วาด <svg> เป็นภาพแยก → ฟอนต์เว็บไม่ตามไป (ชื่อเดือน/ตัวเลขในกราฟกลายเป็นฟอนต์อื่น)
// แก้: ใน onclone ฝัง @font-face (data URI) ลงใน svg ที่มีตัวอักษร และตั้ง font-family ให้ทุก <text>
function igSvgFonts(root) {
  if (!root) return;
  const ff = Object.entries(window.LS_FONT || {}).map(([w, b]) => `@font-face{font-family:'LINE Seed Sans TH';font-weight:${w};src:url(data:font/woff2;base64,${b}) format('woff2')}`).join("");
  root.querySelectorAll("svg").forEach(svg => {
    const t = svg.querySelectorAll("text,tspan"); if (!t.length) return;
    t.forEach(e => e.setAttribute("font-family", "LINE Seed Sans TH"));
    const st = svg.ownerDocument.createElementNS("http://www.w3.org/2000/svg", "style"); st.textContent = ff; svg.insertBefore(st, svg.firstChild);
  });
}
